export function internationalPhone(country,number){const value=String(number||'').trim().replace(/[\s()-]/g,'');if(!value)return '';const region=COUNTRIES.find(c=>c.code===country);if(!region?.dial)throw Error('Choose a country and calling code.');if(value.startsWith('+')){if(!value.startsWith('+'+region.dial)||!/^\+[1-9][0-9]{6,14}$/.test(value))throw Error('Enter a valid phone number matching the selected calling code.');return value;}if(!/^\d+$/.test(value))throw Error('Enter digits only for your phone number.');const national=region.prefix&&value.startsWith(region.prefix)?value.slice(region.prefix.length):value;const phone='+'+region.dial+national;if(!/^\+[1-9][0-9]{6,14}$/.test(phone))throw Error('Enter a valid phone number.');return phone;}
